// Register the app-shell service worker generated by vite-plugin-pwa.
// This module ships to the browser only from src/routes/__root.tsx and gates
// on the same rules the PWA skill mandates, so preview/dev never register.

function shouldRegister(): boolean {
  if (typeof window === "undefined") return false;
  if (!("serviceWorker" in navigator)) return false;
  if (!import.meta.env.PROD) return false;
  try {
    if (window.top !== window.self) return false;
  } catch {
    return false;
  }
  const url = new URL(window.location.href);
  if (url.searchParams.get("sw") === "off") return false;
  const host = url.hostname;
  const bannedPrefix = host.startsWith("id-preview--") || host.startsWith("preview--");
  const bannedHost =
    host === "lovableproject.com" ||
    host.endsWith(".lovableproject.com") ||
    host === "lovableproject-dev.com" ||
    host.endsWith(".lovableproject-dev.com") ||
    host === "beta.lovable.dev" ||
    host.endsWith(".beta.lovable.dev");
  if (bannedPrefix || bannedHost) return false;
  return true;
}

async function unregisterAppSw() {
  try {
    const regs = await navigator.serviceWorker.getRegistrations();
    await Promise.all(
      regs
        .filter((r) => (r.active?.scriptURL || "").endsWith("/sw.js"))
        .map((r) => r.unregister()),
    );
  } catch {
    /* noop */
  }
}

export function registerAppServiceWorker() {
  if (typeof window === "undefined") return;
  if (!shouldRegister()) {
    if ("serviceWorker" in navigator) void unregisterAppSw();
    return;
  }
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("/sw.js").catch(() => {
      /* noop */
    });
  });
}